def can_form_array(s):
    n = len(s)
    # If the string is of length 2, we can always form a consistent array
    if n == 2:
        return "YES" if s != "NE" else "NO"
    # For longer strings, we can always form a consistent array
    return "YES"

def main():
    t = int(input())
    results = []
    for _ in range(t):
        s = input()
        results.append(can_form_array(s))
    for result in results:
        print(result)

